using System.ComponentModel;
using ToonNet.Core.Encoding;

namespace ToonNet.Core.Serialization;

/// <summary>
///     Whether an object can be a row of a tabular array (spec §9.3), as far as its own values tell.
/// </summary>
/// <remarks>Supports code generated by <c>ToonNet.SourceGenerators</c>; not intended to be used directly.</remarks>
[EditorBrowsable(EditorBrowsableState.Never)]
public enum ToonRowShape
{
    /// <summary>Every written value is a primitive; the columns tell which properties are written.</summary>
    Row,

    /// <summary>A written value is an object or array, so the object cannot be a row.</summary>
    NotRow,

    /// <summary>Whether a value is a primitive depends on its runtime type or a converter.</summary>
    Unknown
}

/// <summary>
///     Writes the properties of objects of one type straight to TOON text. Generated code registers one per
///     <c>[ToonSerializable]</c> type, and the serializer uses it instead of building a <c>ToonValue</c> tree.
/// </summary>
/// <remarks>Supports code generated by <c>ToonNet.SourceGenerators</c>; not intended to be used directly.</remarks>
[EditorBrowsable(EditorBrowsableState.Never)]
public abstract class ToonObjectWriter
{
    private protected ToonObjectWriter() { }

    /// <summary>The number of properties; tabular columns are indexed by property.</summary>
    public abstract int PropertyCount { get; }

    /// <summary>The serialized name of the property at <paramref name="index"/> (not encoded).</summary>
    public abstract string GetName(int index, ToonSerializerOptions options);

    internal abstract int WriteFieldsOf(object value, ToonWriter writer, int lineDepth, int childDepth, bool firstOnCurrentLine, int depth);

    internal abstract ToonRowShape GetRowShapeOf(object value, ToonWriter writer, Span<bool> columns);

    internal abstract void WriteRowOf(object value, ToonWriter writer, ReadOnlySpan<bool> columns);
}

/// <summary>
///     Writes the properties of <typeparamref name="T"/> objects straight to TOON text, with the same result as the
///     serializer.
/// </summary>
/// <typeparam name="T">The type whose objects are written.</typeparam>
/// <remarks>Supports code generated by <c>ToonNet.SourceGenerators</c>; not intended to be used directly.</remarks>
[EditorBrowsable(EditorBrowsableState.Never)]
public abstract class ToonObjectWriter<T> : ToonObjectWriter
{
    /// <summary>Creates the writer.</summary>
    protected ToonObjectWriter() { }

    /// <summary>
    ///     Writes the properties as fields: the first on the current line when <paramref name="firstOnCurrentLine"/>
    ///     (a list item), the others on new lines at <paramref name="lineDepth"/>; nested content goes to
    ///     <paramref name="childDepth"/>.
    /// </summary>
    /// <param name="value">The object.</param>
    /// <param name="writer">The writer.</param>
    /// <param name="lineDepth">The depth of the field lines.</param>
    /// <param name="childDepth">The depth of nested content.</param>
    /// <param name="firstOnCurrentLine">Whether the first field continues the current line.</param>
    /// <param name="depth">The serializer depth of the object (its property values are one deeper).</param>
    /// <returns>The number of fields written.</returns>
    public abstract int WriteFields(T value, ToonWriter writer, int lineDepth, int childDepth, bool firstOnCurrentLine, int depth);

    /// <summary>
    ///     Tells whether the object can be a tabular row and, per property, whether it is written (a column).
    /// </summary>
    public abstract ToonRowShape GetRowShape(T value, ToonWriter writer, Span<bool> columns);

    /// <summary>
    ///     Writes the values of the given columns separated by the delimiter, for an object whose shape is
    ///     <see cref="ToonRowShape.Row"/>.
    /// </summary>
    public abstract void WriteRow(T value, ToonWriter writer, ReadOnlySpan<bool> columns);

    internal sealed override int WriteFieldsOf(object value, ToonWriter writer, int lineDepth, int childDepth, bool firstOnCurrentLine,
                                               int depth) =>
        WriteFields((T)value, writer, lineDepth, childDepth, firstOnCurrentLine, depth);

    internal sealed override ToonRowShape GetRowShapeOf(object value, ToonWriter writer, Span<bool> columns) =>
        GetRowShape((T)value, writer, columns);

    internal sealed override void WriteRowOf(object value, ToonWriter writer, ReadOnlySpan<bool> columns) =>
        WriteRow((T)value, writer, columns);
}
